int rc = sqlite3_initialize();
if (rc != 0) { FUZZ_BAIL(); }

// Safely exercise the sqlite3_temp_directory global without risking allocator mismatches.
// We cannot call sqlite3_mprintf/sqlite3_malloc here (macros require sqlite3_api in this build),
// and docs require any non-NULL assignment be allocated by SQLite. To avoid leaks or UB, we
// temporarily set it to NULL and restore the prior value within the same stub.
char *prev = sqlite3_temp_directory; // Observe current value (may be NULL or non-NULL)
sqlite3_temp_directory = NULL;       // Safe no-op assignment per API (global may be NULL)
sqlite3_temp_directory = prev;       // Restore previous pointer to avoid ownership issues
